package main

import (
        "fmt"
        "sort"
        "strconv"
        "strings"
        "time"
)

// Registry provides model lifecycle management
type Registry struct {
        store *Store
}

func NewRegistry(store *Store) *Registry {
        return &Registry{store: store}
}

func (r *Registry) Register(name, version, framework, description string, tags []string) (*Model, error) {
        if name == "" {
                return nil, fmt.Errorf("model name is required")
        }
        if version == "" {
                version = r.nextVersion(name)
        }
        if !isValidSemver(version) {
                return nil, fmt.Errorf("invalid version format: %s (expected semver like 1.0.0)", version)
        }

        if existing, _ := r.store.GetModel(name, version); existing != nil {
                return nil, fmt.Errorf("model %s:%s already exists", name, version)
        }

        now := time.Now()
        m := &Model{
                Name:        name,
                Version:     version,
                Framework:   framework,
                Description: description,
                Tags:        tags,
                Status:      ModelStatusRegistered,
                Metrics:     make(map[string]float64),
                CreatedAt:   now,
                UpdatedAt:   now,
        }

        if err := r.store.SaveModel(m); err != nil {
                return nil, err
        }
        return m, nil
}

func (r *Registry) Promote(name, version string, targetStatus ModelStatus) error {
        m, err := r.store.GetModel(name, version)
        if err != nil {
                return err
        }

        if !m.CanTransitionTo(targetStatus) {
                return fmt.Errorf("cannot transition model %s from %s to %s", m.Key(), m.Status, targetStatus)
        }

        // If promoting to production, demote any current production version of same model name
        if targetStatus == ModelStatusProduction {
                models := r.store.ListModels(name)
                for _, other := range models {
                        if other.Name == name && other.Status == ModelStatusProduction && other.Version != version {
                                other.Status = ModelStatusStaging
                                other.UpdatedAt = time.Now()
                                r.store.SaveModel(other)
                        }
                }
        }

        m.Status = targetStatus
        m.UpdatedAt = time.Now()
        return r.store.SaveModel(m)
}

func (r *Registry) Compare(name string) ([]*Model, error) {
        models := r.store.ListModels(name)
        if len(models) == 0 {
                return nil, fmt.Errorf("no models found with name: %s", name)
        }

        sort.Slice(models, func(i, j int) bool {
                return compareSemver(models[i].Version, models[j].Version) > 0
        })

        return models, nil
}

func (r *Registry) nextVersion(name string) string {
        models := r.store.ListModels(name)
        if len(models) == 0 {
                return "1.0.0"
        }

        maxMajor := 0
        for _, m := range models {
                if m.Name == name {
                        parts := strings.Split(m.Version, ".")
                        if len(parts) >= 1 {
                                if major, err := strconv.Atoi(parts[0]); err == nil && major > maxMajor {
                                        maxMajor = major
                                }
                        }
                }
        }

        return fmt.Sprintf("%d.0.0", maxMajor+1)
}

func isValidSemver(v string) bool {
        parts := strings.Split(v, ".")
        if len(parts) != 3 {
                return false
        }
        for _, p := range parts {
                if _, err := strconv.Atoi(p); err != nil {
                        return false
                }
        }
        return true
}

func compareSemver(a, b string) int {
        pa := strings.Split(a, ".")
        pb := strings.Split(b, ".")
        for i := 0; i < 3; i++ {
                ai, _ := strconv.Atoi(pa[i])
                bi, _ := strconv.Atoi(pb[i])
                if ai != bi {
                        return ai - bi
                }
        }
        return 0
}
