// ValidTransitions defines valid model lifecycle transitions
var ValidTransitions = map[ModelStatus][]ModelStatus{
        ModelStatusRegistered: {ModelStatusStaging, ModelStatusArchived},
        ModelStatusStaging:    {ModelStatusProduction, ModelStatusRegistered, ModelStatusArchived},
        ModelStatusProduction: {ModelStatusStaging, ModelStatusArchived},
        ModelStatusArchived:   {ModelStatusRegistered},
}

