func validatePipelineConfig(cfg *PipelineConfig) error {
	if cfg.Name == "" {
		return fmt.Errorf("pipeline name is required")
	}
	if len(cfg.Steps) == 0 {
		return fmt.Errorf("pipeline must have at least one step")
	}

	names := make(map[string]bool)
	for _, step := range cfg.Steps {
		if step.Name == "" {
			return fmt.Errorf("step name is required")
		}
		if names[step.Name] {
			return fmt.Errorf("duplicate step name: %s", step.Name)
		}
		names[step.Name] = true
		switch step.Type {
		case "shell", "train", "evaluate":
		default:
			return fmt.Errorf("step %s has invalid type: %s", step.Name, step.Type)
		}
		if step.Command == "" {
			return fmt.Errorf("step %s command is required", step.Name)
		}
		if step.Resources != nil && cfg.ResourceLimit != nil {
			if step.Resources.CPU > cfg.ResourceLimit.CPU {
				return fmt.Errorf("step %s cpu requirement %d exceeds pipeline limit %d", step.Name, step.Resources.CPU, cfg.ResourceLimit.CPU)
			}
			if step.Resources.MemoryMB > cfg.ResourceLimit.MemoryMB {
				return fmt.Errorf("step %s memory requirement %d MB exceeds pipeline limit %d MB", step.Name, step.Resources.MemoryMB, cfg.ResourceLimit.MemoryMB)
			}
		}
		if step.Type == "train" && step.ExperimentConfig == nil {
			return fmt.Errorf("train step %s requires experiment_config", step.Name)
		}
	}

	for _, step := range cfg.Steps {
		for _, dep := range step.DependsOn {
			if !names[dep] {
				return fmt.Errorf("step %s depends on unknown step %s", step.Name, dep)
			}
		}
	}

	if cycle := findCycle(cfg.Steps); cycle != nil {
		return fmt.Errorf("cycle detected: %s", strings.Join(cycle, " -> "))
	}

	producers := make(map[string]string)
	for _, step := range cfg.Steps {
		for _, out := range step.Outputs {
			if _, ok := producers[out]; ok {
				return fmt.Errorf("duplicate output artifact: %s", out)
			}
			producers[out] = step.Name
		}
	}

	for _, step := range cfg.Steps {
		for _, in := range step.Inputs {
			prod, ok := producers[in]
			if !ok {
				return fmt.Errorf("step %s input artifact %s is not produced by any step", step.Name, in)
			}
			if prod == step.Name {
				return fmt.Errorf("step %s input artifact %s must come from a dependency", step.Name, in)
			}
			if !isTransitiveDependency(cfg.Steps, step.Name, prod) {
				return fmt.Errorf("step %s input artifact %s producer %s is not a transitive dependency", step.Name, in, prod)
			}
		}
	}
	return nil
}

func findCycle(steps []*PipelineStep) []string {
	graph := make(map[string][]string)
	for _, s := range steps {
		graph[s.Name] = append(graph[s.Name], s.DependsOn...)
	}
	visited := make(map[string]int)
	var stack []string
	var dfs func(node string) []string
	dfs = func(node string) []string {
		visited[node] = 1
		stack = append(stack, node)
		for _, dep := range graph[node] {
			if visited[dep] == 1 {
				for i, n := range stack {
					if n == dep {
						return append(append([]string{}, stack[i:]...), dep)
					}
				}
				return []string{node, dep}
			}
			if visited[dep] == 0 {
				if c := dfs(dep); c != nil {
					return c
				}
			}
		}
		stack = stack[:len(stack)-1]
		visited[node] = 2
		return nil
	}
	for _, s := range steps {
		if visited[s.Name] == 0 {
			if c := dfs(s.Name); c != nil {
				return c
			}
		}
	}
	return nil
}

func isTransitiveDependency(steps []*PipelineStep, step, target string) bool {
	byName := make(map[string]*PipelineStep)
	for _, s := range steps {
		byName[s.Name] = s
	}
	var visit func(current string) bool
	visit = func(current string) bool {
		s := byName[current]
		for _, dep := range s.DependsOn {
			if dep == target {
				return true
			}
			if visit(dep) {
				return true
			}
		}
		return false
	}
	return visit(step)
}

func runPipeline(cfg *PipelineConfig, tracker *Tracker, params map[string]string, maxParallel int) (*PipelineRun, error) {
	if err := validatePipelineConfig(cfg); err != nil {
		return nil, err
	}
	merged := mergeParams(cfg.Parameters, params)
	if maxParallel <= 0 {
		maxParallel = cfg.MaxParallel
	}
	if maxParallel <= 0 {
		maxParallel = 4
	}

	runID := generateRunID()
	runDir := filepath.Join(pipelineRunsDir, runID)
	artifactsDir := filepath.Join(runDir, "artifacts")
	if err := os.MkdirAll(artifactsDir, 0755); err != nil {
		return nil, fmt.Errorf("create run dir: %w", err)
	}

	now := time.Now()
	run := &PipelineRun{
		ID:         runID,
		Pipeline:   cfg.Name,
		Status:     "running",
		Parameters: merged,
		StartTime:  &now,
		RunDir:     runDir,
		Steps:      make([]*StepRun, 0, len(cfg.Steps)),
	}
	for _, step := range cfg.Steps {
		run.Steps = append(run.Steps, &StepRun{Name: step.Name, Type: step.Type, Status: "pending"})
	}
	saveRun(run)

	err := executeSteps(cfg, run, tracker, merged, maxParallel)
	endTime := time.Now()
	run.EndTime = &endTime
	if err != nil {
		run.Status = "failed"
	} else {
		run.Status = "succeeded"
	}
	saveRun(run)
	return run, err
}

func executeSteps(cfg *PipelineConfig, run *PipelineRun, tracker *Tracker, params map[string]string, maxParallel int) error {
	stepByName := make(map[string]*PipelineStep)
	for _, s := range cfg.Steps {
		stepByName[s.Name] = s
	}
	runStepByName := make(map[string]*StepRun)
	for _, sr := range run.Steps {
		runStepByName[sr.Name] = sr
	}

	artifactProducer := make(map[string]string)
	for _, step := range cfg.Steps {
		for _, out := range step.Outputs {
			artifactProducer[out] = step.Name
		}
	}

	var mu sync.Mutex
	var running []*PipelineStep
	available := make(chan struct{}, maxParallel)

	pending := make(map[string]bool)
	for _, step := range cfg.Steps {
		pending[step.Name] = true
	}

	var wg sync.WaitGroup
	done := false

	canStart := func(step *PipelineStep) bool {
		for _, dep := range step.DependsOn {
			status := runStepByName[dep].Status
			if status != "succeeded" && status != "skipped" {
				return false
			}
		}
		if step.Resources != nil && cfg.ResourceLimit != nil {
			var cpu, mem int
			for _, r := range running {
				if r.Resources != nil {
					cpu += r.Resources.CPU
					mem += r.Resources.MemoryMB
				}
			}
			if cpu+step.Resources.CPU > cfg.ResourceLimit.CPU || mem+step.Resources.MemoryMB > cfg.ResourceLimit.MemoryMB {
				return false
			}
		}
		return true
	}

	startStep := func(step *PipelineStep) {
		pending[step.Name] = false
		running = append(running, step)
		wg.Add(1)
		go func(s *PipelineStep) {
			defer wg.Done()
			executeStep(cfg, run, tracker, s, params, runStepByName[s.Name])
			mu.Lock()
			running = removeStep(running, s)
			if run.Status == "failed" {
				done = true
			}
			saveCheckpoint(run)
			saveRun(run)
			mu.Unlock()
			<-available
		}(step)
	}

	for !done && (len(pending) > 0 || len(running) > 0) {
		startedAny := false
		var starts []*PipelineStep
		mu.Lock()
		for _, step := range cfg.Steps {
			if pending[step.Name] && canStart(step) {
				starts = append(starts, step)
			}
		}
		mu.Unlock()
		sort.Slice(starts, func(i, j int) bool { return starts[i].Name < starts[j].Name })
		for _, step := range starts {
			available <- struct{}{}
			mu.Lock()
			if done || !pending[step.Name] || !canStart(step) {
				mu.Unlock()
				<-available
				continue
			}
			startStep(step)
			mu.Unlock()
			startedAny = true
		}

		if !startedAny {
			if len(running) == 0 {
				break
			}
			time.Sleep(10 * time.Millisecond)
		}
	}
	wg.Wait()

	for _, sr := range run.Steps {
		if sr.Status == "pending" {
			sr.Status = "skipped"
			sr.Error = "dependency failed"
		}
	}
	saveCheckpoint(run)
	saveRun(run)

	if run.Status == "failed" {
		return fmt.Errorf("pipeline execution failed")
	}
	return nil
}

func removeStep(steps []*PipelineStep, target *PipelineStep) []*PipelineStep {
	out := make([]*PipelineStep, 0, len(steps))
	for _, s := range steps {
		if s != target {
			out = append(out, s)
		}
	}
	return out
}

func executeStep(cfg *PipelineConfig, run *PipelineRun, tracker *Tracker, step *PipelineStep, params map[string]string, sr *StepRun) {
	runDir := run.RunDir
	for _, dep := range step.DependsOn {
		depStatus := getRunStep(run, dep).Status
		if depStatus != "succeeded" && depStatus != "skipped" {
			sr.Status = "failed"
			sr.Error = "dependency failed"
			return
		}
	}

	if step.Condition != "" {
		cond, err := evaluateCondition(step.Condition, params)
		if err != nil {
			sr.Status = "failed"
			sr.Error = err.Error()
			return
		}
		if !cond {
			sr.Status = "skipped"
			sr.Output = "condition false"
			return
		}
	}

	maxRetries := 0
	backoffBase := 1
	if step.Retry != nil {
		maxRetries = step.Retry.MaxRetries
		if step.Retry.BackoffBaseSeconds > 0 {
			backoffBase = step.Retry.BackoffBaseSeconds
		}
	}

	cmdStr := substituteParams(step.Command, params)
	for attempt := 0; attempt <= maxRetries; attempt++ {
		start := time.Now()
		sr.StartTime = &start
		sr.RetryCount = attempt
		out, exitCode, err := runShellCommand(cmdStr, step.TimeoutSeconds)
		sr.Output = out
		sr.ExitCode = exitCode
		if err == nil {
			sr.EndTime = nowPtr()
			sr.Status = "succeeded"
			sr.Error = ""
			produceArtifacts(run, step, sr, out)
			if step.Type == "train" {
				expID, terr := handleTrainExperiment(tracker, step, out, sr.ExperimentID)
				if terr != nil {
					sr.Status = "failed"
					sr.Error = terr.Error()
				} else {
					sr.ExperimentID = expID
				}
			}
			if step.Type == "evaluate" {
				registerEvaluateArtifacts(run, step, sr)
			}
			return
		}
		sr.Error = err.Error()
		if attempt < maxRetries {
			delay := time.Duration(math.Pow(float64(backoffBase), float64(attempt+1))) * time.Second
			time.Sleep(delay)
		}
	}
	sr.EndTime = nowPtr()
	sr.Status = "failed"
}

