func handleTrainExperiment(tracker *Tracker, step *PipelineStep, output string, existingID string) (string, error) {
	expName := step.Name
	var params map[string]string
	var tags []string
	if step.ExperimentConfig != nil {
		if step.ExperimentConfig.Name != "" {
			expName = step.ExperimentConfig.Name
		}
		params = step.ExperimentConfig.Params
	}

	var exp *Experiment
	var err error
	if existingID != "" {
		exp, err = tracker.store.GetExperiment(existingID)
		if err != nil {
			exp, err = tracker.Create(expName, params, tags)
			}
	} else {
		exp, err = tracker.Create(expName, params, tags)
	}
	if err != nil {
		return "", err
	}
	for _, line := range strings.Split(output, "\n") {
		key, value, ok := parseMetricLine(line)
		if !ok {
			continue
		}
		if len(step.ExperimentConfig.Metrics) > 0 && !containsString(step.ExperimentConfig.Metrics, key) {
			continue
		}
		if lerr := tracker.LogMetric(exp.ID, key, value); lerr != nil {
			err = lerr
		}
	}
	if err != nil {
		tracker.Complete(exp.ID, ExperimentStatusFailed)
		return exp.ID, err
	}
	tracker.Complete(exp.ID, ExperimentStatusCompleted)
	return exp.ID, nil
}

func parseMetricLine(line string) (string, float64, bool) {
	parts := strings.SplitN(line, "=", 2)
	if len(parts) != 2 {
		return "", 0, false
	}
	key := strings.TrimSpace(parts[0])
	val := strings.TrimSpace(parts[1])
	if key == "" {
		return "", 0, false
	}
	value, err := strconv.ParseFloat(val, 64)
	if err != nil {
		return "", 0, false
	}
	return key, value, true
}

func runShellCommand(command string, timeoutSeconds int) (string, int, error) {
	cmd := exec.Command("sh", "-c", command)
	var out strings.Builder
	cmd.Stdout = &out
	cmd.Stderr = &out

	if timeoutSeconds > 0 {
		timer := time.AfterFunc(time.Duration(timeoutSeconds)*time.Second, func() {
			if cmd.Process != nil {
				cmd.Process.Kill()
			}
		})
		defer timer.Stop()
	}

	err := cmd.Run()
	exitCode := 0
	if err != nil {
		if exitErr, ok := err.(*exec.ExitError); ok {
			exitCode = exitErr.ExitCode()
		} else {
			exitCode = 1
		}
		return out.String(), exitCode, fmt.Errorf("command failed: %s", err.Error())
	}
	return out.String(), exitCode, nil
}

func produceArtifacts(run *PipelineRun, step *PipelineStep, sr *StepRun, content string) {
	stepArtDir := filepath.Join(run.RunDir, "artifacts", step.Name)
	os.MkdirAll(stepArtDir, 0755)
	for _, name := range step.Outputs {
		path := filepath.Join(stepArtDir, name)
		if err := os.WriteFile(path, []byte(content), 0644); err != nil {
			sr.Error = appendError(sr.Error, fmt.Sprintf("write artifact %s: %v", name, err))
			continue
		}
		info, _ := os.Stat(path)
		var size int64
		if info != nil {
			size = info.Size()
		}
		artType := "data"
		if step.Type == "train" {
			artType = "model"
		} else if step.Type == "evaluate" {
			artType = "metrics"
		}
		artifact := Artifact{Name: name, Type: artType, Producer: step.Name, Path: path, Size: size}
		sr.Artifacts = appendArtifact(sr.Artifacts, artifact)
		run.Artifacts = appendArtifact(run.Artifacts, artifact)
	}
}

func registerEvaluateArtifacts(run *PipelineRun, step *PipelineStep, sr *StepRun) {
	for i, art := range sr.Artifacts {
		if art.Producer == step.Name && (art.Type == "data" || art.Type == "") {
			sr.Artifacts[i].Type = "metrics"
		}
	}
	for i, art := range run.Artifacts {
		if art.Producer == step.Name && (art.Type == "data" || art.Type == "") {
			run.Artifacts[i].Type = "metrics"
		}
	}
}

func appendArtifact(arts []Artifact, art Artifact) []Artifact {
	for i, a := range arts {
		if a.Name == art.Name && a.Producer == art.Producer {
			arts[i] = art
			return arts
		}
	}
	return append(arts, art)
}

func appendError(existing, addition string) string {
	if existing == "" {
		return addition
	}
	return existing + "; " + addition
}

func mergeParams(defaults, overrides map[string]string) map[string]string {
	merged := make(map[string]string)
	for k, v := range defaults {
		merged[k] = v
	}
	for k, v := range overrides {
		merged[k] = v
	}
	return merged
}

func substituteParams(command string, params map[string]string) string {
	result := command
	for k, v := range params {
		result = strings.ReplaceAll(result, "${"+k+"}", v)
	}
	return result
}

func evaluateCondition(cond string, params map[string]string) (bool, error) {
	cond = strings.TrimSpace(cond)
	if cond == "" {
		return true, nil
	}
	if strings.Contains(cond, "==") {
		parts := strings.SplitN(cond, "==", 2)
		left := resolveParam(strings.TrimSpace(parts[0]), params)
		right := resolveParam(strings.TrimSpace(parts[1]), params)
		return left == right, nil
	}
	if strings.Contains(cond, "!=") {
		parts := strings.SplitN(cond, "!=", 2)
		left := resolveParam(strings.TrimSpace(parts[0]), params)
		right := resolveParam(strings.TrimSpace(parts[1]), params)
		return left != right, nil
	}
	return false, fmt.Errorf("invalid condition: %s", cond)
}

func resolveParam(token string, params map[string]string) string {
	re := regexp.MustCompile(`^\$\{(.+)\}$`)
	m := re.FindStringSubmatch(token)
	if m != nil {
		return params[m[1]]
	}
	return token
}

