	}
	var run PipelineRun
	if err := json.Unmarshal(data, &run); err != nil {
		return nil, fmt.Errorf("parse run: %w", err)
	}
	return &run, nil
}

func listRuns() []*PipelineRun {
	entries, err := os.ReadDir(pipelineRunsDir)
	if err != nil {
		return nil
	}
	var runs []*PipelineRun
	for _, entry := range entries {
		if !entry.IsDir() {
			continue
		}
		run, err := loadRun(entry.Name())
		if err != nil {
			continue
		}
		runs = append(runs, run)
	}
	sort.Slice(runs, func(i, j int) bool {
		if runs[i].StartTime == nil || runs[j].StartTime == nil {
			return runs[i].ID < runs[j].ID
		}
		return runs[i].StartTime.Before(*runs[j].StartTime)
	})
	return runs
}

func resumePipeline(runID string, tracker *Tracker) (*PipelineRun, error) {
	run, err := loadRun(runID)
	if err != nil {
		return nil, err
	}
	cpPath := filepath.Join(run.RunDir, "checkpoint.json")
	cpData, err := os.ReadFile(cpPath)
	if err == nil {
		var cp Checkpoint
		if json.Unmarshal(cpData, &cp) == nil {
			run.Status = cp.Status
			run.Parameters = cp.Parameters
			run.Steps = cp.Steps
			run.Artifacts = cp.Artifacts
		}
	}

	cfgPath := filepath.Join(run.RunDir, "pipeline_config.json")
	var cfg *PipelineConfig
	if cfgData, err := os.ReadFile(cfgPath); err == nil {
		var c PipelineConfig
		if json.Unmarshal(cfgData, &c) == nil {
			cfg = &c
		}
	}
	if cfg == nil {
		return nil, fmt.Errorf("pipeline config not found for run %s", runID)
	}

	run.Status = "running"
	saveRun(run)

	err = executeSteps(cfg, run, tracker, run.Parameters, cfg.MaxParallel)
	endTime := time.Now()
	run.EndTime = &endTime
	if err != nil {
		run.Status = "failed"
	} else {
		run.Status = "succeeded"
	}
	saveRun(run)
	return run, err
}

func buildArtifactManifest(run *PipelineRun) map[string]interface{} {
	manifest := map[string]interface{}{
		"artifacts": run.Artifacts,
	}
	lineage := make(map[string][]string)
	cfgStepsByName := make(map[string]*StepRun)
	for _, sr := range run.Steps {
		cfgStepsByName[sr.Name] = sr
	}
	for _, art := range run.Artifacts {
		var consumers []string
		// We do not have the original config here; derive from run outputs is not possible.
		_ = cfgStepsByName
		lineage[art.Name] = consumers
	}
	manifest["lineage"] = lineage
	return manifest
}
