func createTrainExperiment(tracker *Tracker, step *PipelineStep, existingID string) (*Experiment, error) {
        expName := step.Name
        var params map[string]string
        var tags []string
        if step.ExperimentConfig != nil {
                if step.ExperimentConfig.Name != "" {
                        expName = step.ExperimentConfig.Name
                }
                params = step.ExperimentConfig.Params
        }
        if existingID != "" {
                if exp, err := tracker.store.GetExperiment(existingID); err == nil {
                        return exp, nil
                }
        }
        return tracker.Create(expName, params, tags)
}

func finishTrainExperiment(tracker *Tracker, exp *Experiment, step *PipelineStep, output string) error {
        for _, line := range strings.Split(output, "\\n") {
                key, value, ok := parseMetricLine(line)
                if !ok {
                        continue
                }
                if len(step.ExperimentConfig.Metrics) > 0 && !containsString(step.ExperimentConfig.Metrics, key) {
                        continue
                }
                if err := tracker.LogMetric(exp.ID, key, value); err != nil {
                        return err
                }
        }
        return tracker.Complete(exp.ID, ExperimentStatusCompleted)
}

